def transform(g):
    g=[r[:] for r in g]; H,W=len(g),len(g[0])
    # find shapes (connected 5 components) via bounding boxes of nonzero rows/cols groups
    import sys; sys.setrecursionlimit(10000)
    seen=[[False]*W for _ in range(H)]
    def nb(r,c):
        for dr,dc in((1,0),(-1,0),(0,1),(0,-1)):
            yield r+dr,c+dc
    for r0 in range(H):
        for c0 in range(W):
            if g[r0][c0]==5 and not seen[r0][c0]:
                stack=[(r0,c0)]; cells=[]
                seen[r0][c0]=True
                while stack:
                    r,c=stack.pop(); cells.append((r,c))
                    for rr,cc in nb(r,c):
                        if 0<=rr<H and 0<=cc<W and g[rr][cc]==5 and not seen[rr][cc]:
                            seen[rr][cc]=True; stack.append((rr,cc))
                rs=[r for r,c in cells]; cs=[c for r,c in cells]
                top,bot,l,r=min(rs),max(rs),min(cs),max(cs)
                # fill zeros inside bbox with 2
                for rr in range(top,bot+1):
                    for cc in range(l,r+1):
                        if g[rr][cc]==0: g[rr][cc]=2
                # leak column: gap in top row of shape
                gaps=[cc for cc in range(l,r+1) if g[top][cc]==2]  # already filled
                # top-row original gaps: zeros in top row -> now 2; original 5s stay 5
                gaps=[cc for cc in range(l,r+1) if cells and (top,cc) not in [(x,y) for x,y in cells]]
                # better: gap = columns in top row that were 0 originally
                orig=[cc for cc in range(l,r+1) if (top,cc) not in cells]
                if orig:
                    leak=orig[0]
                    center=(l+r)/2
                    step=-1 if leak>center else 1
                    rr=top-1
                    if 0<=rr<H:
                        cc=leak
                        while 0<=cc<W and g[rr][cc]!=5:
                            g[rr][cc]=2; cc+=step
    return g

